const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ── Helpers ────────────────────────────────────────────────────────────────────

function qs(doc, sel) {
  const el = doc.querySelector(sel);
  if (!el) throw new Error(`querySelector("${sel}") returned null`);
  return el;
}

function qsa(doc, sel) { return Array.from(doc.querySelectorAll(sel)); }

function todoItem(doc, text) {
  const items = qsa(doc, '.todo-list li');
  return items.find(li => li.querySelector('label')?.textContent?.trim() === text);
}

function assertTodo(doc, text) {
  const li = todoItem(doc, text);
  if (!li) throw new Error(`Expected todo "${text}" to be in the list`);
  return li;
}

function assertNoTodo(doc, text) {
  const li = todoItem(doc, text);
  if (li) throw new Error(`Expected todo "${text}" NOT to be in the list`);
}

function triggerEvent(el, type, opts = {}) {
  const ev = new (el.ownerDocument.defaultView || window)[`${type[0].toUpperCase()}${type.slice(1)}Event`](type, { bubbles: true, cancelable: true, ...opts });
  // For keyboard events, add key properties
  if (type === 'keydown' || type === 'keyup' || type === 'keypress') {
    Object.assign(ev, opts);
  }
  el.dispatchEvent(ev);
}

function triggerClick(el) {
  el.dispatchEvent(new (el.ownerDocument.defaultView || window).MouseEvent('click', { bubbles: true, cancelable: true }));
}

function triggerDblclick(el) {
  el.dispatchEvent(new (el.ownerDocument.defaultView || window).MouseEvent('dblclick', { bubbles: true, cancelable: true }));
}

function triggerInput(el, value) {
  // Set the value and dispatch input event
  el.value = value;
  el.dispatchEvent(new (el.ownerDocument.defaultView || window).Event('input', { bubbles: true, cancelable: true }));
}

function isHidden(el) {
  if (!el) return true;
  const style = el.ownerDocument.defaultView.getComputedStyle(el);
  return style.display === 'none' || style.visibility === 'hidden' || el.hidden === true;
}

// ── Given ──────────────────────────────────────────────────────────────────────

Given('the app is loaded', function () {
  // The world.js Before hook already loaded the app.
  assert.ok(this.document, 'document exists after load');
  assert.ok(this.window, 'window exists after load');
});

Given('there are no todos', function () {
  // App loads fresh; we clear localStorage for safety
  this.localStorage.removeItem('todos-vanillajs');
  // Reload to get clean state
  this.loadApp();
});

Given('I have a todo {string}', function (text) {
  this.loadApp();
  const input = qs(this.document, '.new-todo');
  input.value = text;
  triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
});

Given('I have todos {string}, {string}, {string}', function (t1, t2, t3) {
  this.loadApp();
  const input = qs(this.document, '.new-todo');
  for (const t of [t1, t2, t3]) {
    input.value = t;
    triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
  }
});

Given('I have a completed todo {string}', function (text) {
  this.loadApp();
  const input = qs(this.document, '.new-todo');
  input.value = text;
  triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
  const li = assertTodo(this.document, text);
  triggerClick(qs(li, '.toggle'));
});

Given('I am editing the todo {string}', function (text) {
  this.loadApp();
  const input = qs(this.document, '.new-todo');
  input.value = text;
  triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
  const li = assertTodo(this.document, text);
  triggerDblclick(qs(li, 'label'));
});

Given('all todos are completed', function () {
  // Create some todos if none exist
  const items = qsa(this.document, '.todo-list li');
  if (items.length === 0) {
    const input = qs(this.document, '.new-todo');
    input.value = 'default todo';
    triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
  }
  triggerClick(qs(this.document, '.toggle-all'));
});

Given('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

// ── When ───────────────────────────────────────────────────────────────────────

When('I type {string} into the new-todo input and press Enter', function (text) {
  const input = qs(this.document, '.new-todo');
  input.value = text;
  triggerEvent(input, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
});

When('I click the toggle checkbox for {string}', function (text) {
  const li = assertTodo(this.document, text);
  triggerClick(qs(li, '.toggle'));
});

When('I click the toggle-all checkbox', function () {
  triggerClick(qs(this.document, '.toggle-all'));
});

When('I double-click the label for {string}', function (text) {
  const li = assertTodo(this.document, text);
  triggerDblclick(qs(li, 'label'));
});

When('I change the text to {string} and press Enter', function (text) {
  const editInput = qs(this.document, '.todo-list li.editing .edit');
  editInput.value = text;
  triggerEvent(editInput, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
});

When('I change the text to {string} and blur', function (text) {
  const editInput = qs(this.document, '.todo-list li.editing .edit');
  editInput.value = text;
  triggerEvent(editInput, 'blur');
});

When('I change the text to {string} and press Escape', function (text) {
  const editInput = qs(this.document, '.todo-list li.editing .edit');
  editInput.value = text;
  triggerEvent(editInput, 'keydown', { key: 'Escape', keyCode: 27, which: 27 });
});

When('I clear the text and press Enter', function () {
  const editInput = qs(this.document, '.todo-list li.editing .edit');
  editInput.value = '';
  triggerEvent(editInput, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
});

When('I click the destroy button for {string}', function (text) {
  const li = assertTodo(this.document, text);
  triggerClick(qs(li, '.destroy'));
});

When('I complete the todo {string}', function (text) {
  const li = assertTodo(this.document, text);
  triggerClick(qs(li, '.toggle'));
});

When('I uncomplete the todo {string}', function (text) {
  const li = assertTodo(this.document, text);
  triggerClick(qs(li, '.toggle'));
});

When('I click {string}', function (buttonText) {
  if (buttonText === 'Clear completed') {
    triggerClick(qs(this.document, '.clear-completed'));
  }
});

When('I reload the app', function () {
  this.loadApp();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I type {string} into the edit input and press Enter', function (text) {
  const editInput = qs(this.document, '.todo-list li.editing .edit');
  editInput.value = text;
  triggerEvent(editInput, 'keydown', { key: 'Enter', keyCode: 13, which: 13 });
});

// ── Then ───────────────────────────────────────────────────────────────────────

Then('the {string} section is hidden', function (sectionId) {
  const el = qs(this.document, sectionId);
  assert.ok(isHidden(el) || el.style.display === 'none', `Expected ${sectionId} to be hidden`);
});

Then('I see {int} todo(s) in the list', function (count) {
  const items = qsa(this.document, '.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todos, found ${items.length}`);
});

Then('the new-todo input is cleared', function () {
  assert.strictEqual(qs(this.document, '.new-todo').value, '');
});

Then('the todo text is {string}', function (text) {
  const items = qsa(this.document, '.todo-list li');
  const labels = items.map(li => li.querySelector('label')?.textContent?.trim());
  assert.ok(labels.includes(text), `Expected a todo with text "${text}" among [${labels.join(', ')}]`);
});

Then('the todo {string} has class {string}', function (text, className) {
  const li = assertTodo(this.document, text);
  assert.ok(li.classList.contains(className), `Expected todo "${text}" to have class "${className}"`);
});

Then('the todo {string} does not have class {string}', function (text, className) {
  const li = assertTodo(this.document, text);
  assert.ok(!li.classList.contains(className), `Expected todo "${text}" NOT to have class "${className}"`);
});

Then('the toggle checkbox for {string} is checked', function (text) {
  const li = assertTodo(this.document, text);
  const cb = qs(li, '.toggle');
  assert.ok(cb.checked, `Expected toggle for "${text}" to be checked`);
});

Then('the toggle checkbox for {string} is not checked', function (text) {
  const li = assertTodo(this.document, text);
  const cb = qs(li, '.toggle');
  assert.ok(!cb.checked, `Expected toggle for "${text}" to NOT be checked`);
});

Then('the toggle-all checkbox is checked', function () {
  const cb = qs(this.document, '.toggle-all');
  assert.ok(cb.checked, 'Expected toggle-all to be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const cb = qs(this.document, '.toggle-all');
  assert.ok(!cb.checked, 'Expected toggle-all to NOT be checked');
});

Then('all todos are completed', function () {
  const items = qsa(this.document, '.todo-list li');
  assert.ok(items.length > 0, 'There should be at least one todo');
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), `Expected todo "${li.querySelector('label')?.textContent?.trim()}" to be completed`);
  });
});

Then('the edit input for {string} is focused', function (text) {
  const li = assertTodo(this.document, text);
  const editInput = qs(li, '.edit');
  assert.strictEqual(this.document.activeElement, editInput, `Expected edit input for "${text}" to be focused`);
});

Then('the todo-count shows {string}', function (expected) {
  const countEl = qs(this.document, '.todo-count');
  assert.strictEqual(countEl.textContent.trim(), expected);
});

Then('the clear-completed button is hidden', function () {
  const btn = qs(this.document, '.clear-completed');
  assert.ok(isHidden(btn), 'Expected clear-completed to be hidden');
});

Then('the {string} filter link has class {string}', function (filterName, className) {
  const links = qsa(this.document, '.filters a');
  const link = links.find(a => a.textContent.trim() === filterName);
  if (!link) throw new Error(`No filter link "${filterName}" found`);
  assert.ok(link.classList.contains(className), `Expected filter "${filterName}" to have class "${className}"`);
});

Then('the todo {string} is not in the list', function (text) {
  assertNoTodo(this.document, text);
});

Then('the new-todo input has focus', function () {
  const input = qs(this.document, '.new-todo');
  assert.strictEqual(this.document.activeElement, input, 'Expected new-todo input to be focused');
});

/*global app*/
'use strict';

var ENTER_KEY = 13;
var ESCAPE_KEY = 27;
var STORAGE_KEY = 'todos-vanillajs';

// ── Todo Model ─────────────────────────────────────────────────────────────────

function TodoModel(storageKey) {
  this.storageKey = storageKey || STORAGE_KEY;
  this.todos = this.load();
}

TodoModel.prototype.load = function () {
  try {
    var data = localStorage.getItem(this.storageKey);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    return [];
  }
};

TodoModel.prototype.save = function () {
  localStorage.setItem(this.storageKey, JSON.stringify(this.todos));
};

TodoModel.prototype.nextId = function () {
  var max = 0;
  for (var i = 0; i < this.todos.length; i++) {
    if (this.todos[i].id > max) max = this.todos[i].id;
  }
  return max + 1;
};

TodoModel.prototype.add = function (title) {
  var todo = {
    id: this.nextId(),
    title: title,
    completed: false
  };
  this.todos.push(todo);
  this.save();
  return todo;
};

TodoModel.prototype.findById = function (id) {
  for (var i = 0; i < this.todos.length; i++) {
    if (this.todos[i].id === id) return this.todos[i];
  }
  return null;
};

TodoModel.prototype.update = function (id, updates) {
  var todo = this.findById(id);
  if (!todo) return;
  for (var key in updates) {
    if (updates.hasOwnProperty(key)) {
      todo[key] = updates[key];
    }
  }
  this.save();
};

TodoModel.prototype.remove = function (id) {
  this.todos = this.todos.filter(function (t) { return t.id !== id; });
  this.save();
};

TodoModel.prototype.clearCompleted = function () {
  this.todos = this.todos.filter(function (t) { return !t.completed; });
  this.save();
};

TodoModel.prototype.toggleAll = function (checked) {
  for (var i = 0; i < this.todos.length; i++) {
    this.todos[i].completed = checked;
  }
  this.save();
};

TodoModel.prototype.getActive = function () {
  return this.todos.filter(function (t) { return !t.completed; });
};

TodoModel.prototype.getCompleted = function () {
  return this.todos.filter(function (t) { return t.completed; });
};

// ── Todo View ──────────────────────────────────────────────────────────────────

function TodoView(model) {
  this.model = model;
  this.todoList = document.querySelector('.todo-list');
  this.main = document.querySelector('.main');
  this.footer = document.querySelector('.footer');
  this.newTodo = document.querySelector('.new-todo');
  this.toggleAll = document.querySelector('.toggle-all');
  this.todoCount = document.querySelector('.todo-count');
  this.clearCompleted = document.querySelector('.clear-completed');
  this.filters = document.querySelectorAll('.filters a');

  this.currentFilter = 'all';

  this.bindEvents();
  this.render();
}

TodoView.prototype.bindEvents = function () {
  var self = this;

  // New todo: Enter key
  this.newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      var title = self.newTodo.value.trim();
      if (title) {
        self.model.add(title);
        self.newTodo.value = '';
        self.render();
      }
    }
  });

  // Toggle all
  this.toggleAll.addEventListener('change', function () {
    self.model.toggleAll(self.toggleAll.checked);
    self.render();
  });

  // Clear completed
  this.clearCompleted.addEventListener('click', function () {
    self.model.clearCompleted();
    self.render();
  });

  // Event delegation for todo list items
  this.todoList.addEventListener('click', function (e) {
    var li = self._getLi(e.target);
    if (!li) return;

    // Toggle checkbox
    if (e.target.classList.contains('toggle')) {
      var id = parseInt(li.dataset.id, 10);
      var todo = self.model.findById(id);
      if (todo) {
        self.model.update(id, { completed: !todo.completed });
        self.render();
      }
    }

    // Destroy button
    if (e.target.classList.contains('destroy')) {
      var id = parseInt(li.dataset.id, 10);
      self.model.remove(id);
      self.render();
    }
  });

  // Double-click to edit
  this.todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    self._editTodo(li);
  });

  // Routing
  window.addEventListener('hashchange', function () {
    self._updateFilter();
    self.render();
  });

  // Initial filter from URL
  this._updateFilter();
};

TodoView.prototype._updateFilter = function () {
  var hash = window.location.hash || '#/';
  if (hash === '#/' || hash === '' || hash === '#') {
    this.currentFilter = 'all';
  } else if (hash === '#/active') {
    this.currentFilter = 'active';
  } else if (hash === '#/completed') {
    this.currentFilter = 'completed';
  }
};

TodoView.prototype._getLi = function (el) {
  while (el && el.tagName !== 'LI') {
    el = el.parentNode;
  }
  return el;
};

TodoView.prototype._editTodo = function (li) {
  var self = this;
  var id = parseInt(li.dataset.id, 10);
  var todo = this.model.findById(id);
  if (!todo) return;

  var label = li.querySelector('label');
  var editInput = li.querySelector('.edit');
  var originalTitle = todo.title;

  li.classList.add('editing');
  editInput.value = todo.title;
  editInput.focus();

  // Save on Enter
  function onKeydown(e) {
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      editInput.blur();
    }
    if (e.keyCode === ESCAPE_KEY) {
      editInput.value = originalTitle;
      li.classList.remove('editing');
      cleanup();
    }
  }

  // Save on blur
  function onBlur() {
    var title = editInput.value.trim();
    if (title) {
      self.model.update(id, { title: title });
    } else {
      self.model.remove(id);
    }
    li.classList.remove('editing');
    cleanup();
    self.render();
  }

  function cleanup() {
    editInput.removeEventListener('keydown', onKeydown);
    editInput.removeEventListener('blur', onBlur);
  }

  editInput.addEventListener('keydown', onKeydown);
  editInput.addEventListener('blur', onBlur);
};

TodoView.prototype._getFilteredTodos = function () {
  if (this.currentFilter === 'active') {
    return this.model.getActive();
  }
  if (this.currentFilter === 'completed') {
    return this.model.getCompleted();
  }
  return this.model.todos;
};

TodoView.prototype.render = function () {
  var filtered = this._getFilteredTodos();
  var allTodos = this.model.todos;
  var activeCount = this.model.getActive().length;
  var completedCount = this.model.getCompleted().length;

  // Render todo list
  this.todoList.innerHTML = '';
  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');

    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + this._escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + this._escapeHtml(todo.title) + '">';

    this.todoList.appendChild(li);
  }

  // Main visibility
  this.main.style.display = allTodos.length > 0 ? 'block' : 'none';
  this.footer.style.display = allTodos.length > 0 ? 'block' : 'none';

  // Toggle-all state
  this.toggleAll.checked = allTodos.length > 0 && activeCount === 0;

  // Todo count
  var word = activeCount === 1 ? 'item' : 'items';
  this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

  // Clear completed visibility
  this.clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

  // Filter selected class
  for (var j = 0; j < this.filters.length; j++) {
    var a = this.filters[j];
    a.classList.remove('selected');
    var href = a.getAttribute('href');
    if ((this.currentFilter === 'all' && (href === '#/' || href === '#')) ||
        (this.currentFilter === 'active' && href === '#/active') ||
        (this.currentFilter === 'completed' && href === '#/completed')) {
      a.classList.add('selected');
    }
  }
};

TodoView.prototype._escapeHtml = function (str) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(str));
  return div.innerHTML;
};

